/* MarkDowner — Markdown rendering pipeline.
 *
 *   marked (parse) -> DOMPurify (sanitise) -> DOM post-pass -> KaTeX (math)
 *
 * Why a DOM post-pass instead of custom marked renderers: marked's renderer
 * signature has churned across majors (v5 `(text, level)` -> v18 token
 * objects), and a sanitised tree is the only thing safe to hand to the page.
 * Post-processing real DOM nodes is version-proof and lets the browser's own
 * parser handle nesting.
 *
 * Security invariant: after `sanitize()` the only HTML we inject is KaTeX's own
 * output, which is generated by a library from a string we never execute.
 */
(function (MD) {
  'use strict';

  var el = MD.dom.el;
  var escapeHtml = MD.util.escapeHtml;
  var slugify = MD.util.slugify;
  var truncate = MD.util.truncate;

  /* ==========================================================================
   * 1. Math extraction
   *
   * Math must survive marked (which would eat backslashes and underscores) and
   * DOMPurify (which would strip KaTeX's MathML). So we lift it out before
   * parsing and splice it back in after sanitising.
   *
   * Critical detail: math inside fenced code blocks is NOT math. We split the
   * source into fence/non-fence segments and only scan the latter.
   * ======================================================================= */

  var MATH_OPEN = '\u2060M';
  var MATH_CLOSE = 'M\u2060';

  function katexLib() {
    return typeof katex !== 'undefined' ? katex : null;
  }

  function renderTex(tex, displayMode) {
    var lib = katexLib();
    if (!lib) return null;
    try {
      return lib.renderToString(tex, {
        displayMode: displayMode,
        throwOnError: false,
        strict: false,
        trust: false,
        output: 'htmlAndMathml'
      });
    } catch (err) {
      return null;
    }
  }

  function stash(store, html) {
    store.push(html);
    return MATH_OPEN + (store.length - 1) + MATH_CLOSE;
  }

  var RE_FENCE_BOUNDARY = /^(\s{0,3})(`{3,}|~{3,})/;

  /** Split source into [{ text, code:boolean }] honouring fenced code blocks. */
  function segmentByFence(source) {
    var lines = String(source).split('\n');
    var segments = [];
    var buffer = [];
    var inFence = false;
    var fenceChar = '';
    var bufferIsCode = false;

    function flush() {
      if (!buffer.length) return;
      segments.push({ text: buffer.join('\n'), code: bufferIsCode });
      buffer = [];
    }

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      var boundary = RE_FENCE_BOUNDARY.exec(line);
      if (!inFence && boundary) {
        flush();
        inFence = true;
        fenceChar = boundary[2].charAt(0);
        bufferIsCode = true;
        buffer.push(line);
        continue;
      }
      if (inFence) {
        buffer.push(line);
        var closer = new RegExp('^\\s{0,3}' + (fenceChar === '`' ? '`{3,}' : '~{3,}') + '\\s*$');
        if (closer.test(line)) {
          flush();
          inFence = false;
          bufferIsCode = false;
        }
        continue;
      }
      if (!buffer.length) bufferIsCode = false;
      buffer.push(line);
    }
    flush();
    return segments;
  }

  var RE_DISPLAY_DOLLAR = /\$\$([\s\S]+?)\$\$/g;
  var RE_DISPLAY_BRACKET = /\\\[([\s\S]+?)\\\]/g;
  var RE_INLINE_PAREN = /\\\(([\s\S]+?)\\\)/g;

  /**
   * Inline `$...$` scanner. Written by hand rather than by regex because the
   * delimiter rules (no space immediately inside, not escaped, must close on
   * the same line) are easier to state as a loop than as one pattern — and it
   * avoids a lookbehind, which older engines reject outright.
   */
  function replaceInlineDollar(text, store) {
    var out = '';
    var i = 0;
    while (i < text.length) {
      var ch = text.charAt(i);
      if (ch === '\\') {
        out += text.substr(i, 2);
        i += 2;
        continue;
      }
      if (ch !== '$' || text.charAt(i + 1) === '$') {
        out += ch;
        i += 1;
        continue;
      }
      var next = text.charAt(i + 1);
      if (next === '' || /\s/.test(next)) { out += ch; i += 1; continue; }
      var end = -1;
      for (var j = i + 1; j < text.length; j++) {
        var c = text.charAt(j);
        if (c === '\\') { j += 1; continue; }
        if (c === '\n') break;
        if (c === '$') {
          if (text.charAt(j + 1) === '$') { j += 1; continue; }
          if (/\s/.test(text.charAt(j - 1))) continue;
          end = j;
          break;
        }
      }
      if (end === -1) { out += ch; i += 1; continue; }
      var tex = text.slice(i + 1, end);
      var html = renderTex(tex, false);
      out += html ? stash(store, html) : text.slice(i, end + 1);
      i = end + 1;
    }
    return out;
  }

  function replaceSegment(text, store) {
    var out = text.replace(RE_DISPLAY_DOLLAR, function (match, tex) {
      if (!tex.trim()) return match;
      var html = renderTex(tex, true);
      return html ? stash(store, html) : match;
    });
    out = out.replace(RE_DISPLAY_BRACKET, function (match, tex) {
      var html = renderTex(tex, true);
      return html ? stash(store, html) : match;
    });
    out = out.replace(RE_INLINE_PAREN, function (match, tex) {
      var html = renderTex(tex, false);
      return html ? stash(store, html) : match;
    });
    return replaceInlineDollar(out, store);
  }

  function extractMath(source) {
    var store = [];
    var segments = segmentByFence(source);
    var out = segments.map(function (segment) {
      return segment.code ? segment.text : replaceSegment(segment.text, store);
    }).join('\n');
    return { source: out, store: store };
  }

  var RE_PLACEHOLDER = new RegExp(MATH_OPEN + '(\\d+)' + MATH_CLOSE, 'g');

  function restoreMath(root, store) {
    if (!store.length) return;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    var targets = [];
    var node;
    while ((node = walker.nextNode())) {
      if (node.nodeValue.indexOf(MATH_OPEN) !== -1) targets.push(node);
    }
    targets.forEach(function (textNode) {
      var parts = textNode.nodeValue.split(
        new RegExp('(' + MATH_OPEN + '\\d+' + MATH_CLOSE + ')')
      );
      var frag = document.createDocumentFragment();
      parts.forEach(function (part) {
        RE_PLACEHOLDER.lastIndex = 0;
        var m = RE_PLACEHOLDER.exec(part);
        if (m && m[0] === part) {
          var holder = el('span', { className: 'katex-holder' });
          holder.innerHTML = store[Number(m[1])] || '';
          while (holder.firstChild) frag.appendChild(holder.firstChild);
        } else if (part) {
          frag.appendChild(document.createTextNode(part));
        }
      });
      if (textNode.parentNode) textNode.parentNode.replaceChild(frag, textNode);
    });
  }

  /* ==========================================================================
   * 2. marked configuration
   * ======================================================================= */

  var markedConfigured = false;

  function configureMarked() {
    if (markedConfigured || typeof marked === 'undefined') return;
    markedConfigured = true;
    var options = { gfm: true, breaks: false, async: false, headerIds: false, mangle: false };
    try {
      marked.setOptions(options);
    } catch (err) {
      // v18 removed headerIds/mangle from the public option surface; setOptions
      // tolerates unknown keys, but never let a version difference be fatal.
    }
  }

  function parseMarkdown(source) {
    if (typeof marked === 'undefined') {
      return '<p>' + escapeHtml(source) + '</p>';
    }
    configureMarked();
    try {
      return marked.parse(source, { gfm: true, breaks: false, async: false });
    } catch (err) {
      return '<p>' + escapeHtml(source) + '</p>';
    }
  }

  /* ==========================================================================
   * 3. Sanitiser
   *
   * The allow-list is explicit and narrow. Anything not named here is dropped.
   * `input` is admitted only so GFM task-list checkboxes survive; the post-pass
   * deletes every input that is not a disabled checkbox.
   * ======================================================================= */

  var KATEX_TAGS = [
    'math', 'semantics', 'annotation', 'mrow', 'mi', 'mo', 'mn', 'msup', 'msub',
    'msubsup', 'msqrt', 'mroot', 'mfrac', 'mtext', 'mspace', 'mover', 'munder',
    'munderover', 'mtable', 'mtr', 'mtd', 'mstyle', 'mpadded', 'mphantom',
    'menclose', 'svg', 'path', 'g', 'use', 'defs', 'rect', 'circle', 'line',
    'polygon', 'polyline', 'ellipse'
  ];

  var KATEX_ATTRS = [
    'viewBox', 'd', 'fill', 'stroke', 'stroke-width', 'stroke-linecap',
    'stroke-linejoin', 'x', 'y', 'x1', 'y1', 'x2', 'y2', 'cx', 'cy', 'r', 'rx',
    'ry', 'width', 'height', 'transform', 'preserveAspectRatio', 'xmlns',
    'mathvariant', 'displaystyle', 'scriptlevel', 'encoding', 'stretchy',
    'minsize', 'maxsize', 'aria-hidden', 'aria-label', 'role'
  ];

  var PURIFY_CONFIG = {
    USE_PROFILES: { html: true },
    ADD_TAGS: [
      'figure', 'figcaption', 'mark', 'kbd', 'abbr', 'sub', 'sup', 'small',
      'details', 'summary', 'dl', 'dt', 'dd', 'ins', 'del', 'samp', 'var',
      'time', 'wbr', 'input', 'section', 'header', 'footer'
    ].concat(KATEX_TAGS),
    ADD_ATTR: [
      'id', 'class', 'style', 'colspan', 'rowspan', 'align', 'start', 'value',
      'checked', 'disabled', 'type', 'open', 'target', 'rel', 'loading',
      'decoding', 'data-lang', 'data-external', 'data-broken'
    ].concat(KATEX_ATTRS),
    FORBID_TAGS: [
      'script', 'style', 'iframe', 'object', 'embed', 'form', 'button',
      'link', 'meta', 'base', 'textarea', 'select', 'option', 'audio', 'video',
      'source', 'track', 'frame', 'frameset', 'applet', 'template'
    ],
    FORBID_ATTR: ['srcdoc', 'formaction', 'action', 'ping', 'background'],
    ALLOW_DATA_ATTR: false,
    ALLOW_ARIA_ATTR: true,
    KEEP_CONTENT: true
  };

  // DOMPurify runs an event-attribute stripper for us; belt and braces by
  // naming the ones that matter for the elements we admit.
  PURIFY_CONFIG.FORBID_ATTR = PURIFY_CONFIG.FORBID_ATTR.concat([
    'onerror', 'onload', 'onclick', 'onmouseover', 'onmouseenter', 'onfocus',
    'onblur', 'oninput', 'onchange', 'onsubmit', 'onanimationstart',
    'ontransitionend', 'onbegin'
  ]);

  function sanitize(html) {
    if (typeof DOMPurify === 'undefined') return html;
    try {
      return DOMPurify.sanitize(html, PURIFY_CONFIG);
    } catch (err) {
      return '<p>' + escapeHtml(String(html).replace(/<[^>]*>/g, '')) + '</p>';
    }
  }

  /* ==========================================================================
   * 4. DOM post-pass
   * ======================================================================= */

  var HEADING_LEVELS = { H1: 1, H2: 2, H3: 3, H4: 4, H5: 5, H6: 6 };

  var CALLOUT_KEYWORDS = {
    NOTE: 'note', TIP: 'tip', WARNING: 'warning',
    IMPORTANT: 'important', CAUTION: 'caution'
  };

  function postProcess(root) {
    var usedIds = Object.create(null);
    var headings = [];
    var nodes = Array.prototype.slice.call(root.querySelectorAll('*'));

    for (var i = 0; i < nodes.length; i++) {
      var node = nodes[i];
      var tag = node.tagName;

      if (HEADING_LEVELS[tag]) {
        decorateHeading(node, HEADING_LEVELS[tag], usedIds, headings);
      } else if (tag === 'A') {
        decorateLink(node);
      } else if (tag === 'IMG') {
        decorateImage(node);
      } else if (tag === 'PRE') {
        decorateCodeBlock(node);
      } else if (tag === 'TABLE') {
        wrapTable(node);
      } else if (tag === 'BLOCKQUOTE') {
        convertCallout(node);
      } else if (tag === 'INPUT') {
        guardInput(node);
      } else if (tag === 'HR') {
        decorateRule(node);
      }
    }

    markTaskLists(root);
    return headings;
  }

  function decorateHeading(node, level, usedIds, headings) {
    var text = node.textContent.trim();
    var base = slugify(text) || 'section';
    var id = base;
    var counter = 1;
    while (usedIds[id]) { id = base + '-' + (++counter); }
    usedIds[id] = true;
    node.id = id;
    headings.push({ id: id, level: level, text: text });

    var anchor = el('a', {
      className: 'heading-anchor',
      href: '#' + id,
      tabIndex: '-1',
      'aria-hidden': 'true'
    });
    anchor.textContent = '#';
    node.appendChild(anchor);
  }

  function decorateLink(node) {
    var href = (node.getAttribute('href') || '').trim();
    if (!href) { node.removeAttribute('href'); return; }
    if (/^\s*javascript:/i.test(href) || /^\s*data:/i.test(href)) {
      node.removeAttribute('href');
      return;
    }
    if (href.charAt(0) === '#' || href.indexOf('mailto:') === 0 || href.indexOf('tel:') === 0) return;
    if (!/^[a-z][a-z0-9+.-]*:/i.test(href)) return; // relative: leave for the host
    node.setAttribute('data-external', 'true');
    node.setAttribute('target', '_blank');
    node.setAttribute('rel', 'noopener noreferrer');
  }

  function decorateImage(node) {
    var src = node.getAttribute('src') || '';
    if (/^\s*(javascript|vbscript):/i.test(src)) { node.remove(); return; }
    node.setAttribute('loading', 'lazy');
    node.setAttribute('decoding', 'async');
    node.addEventListener('error', function onError() {
      node.removeEventListener('error', onError);
      node.setAttribute('data-broken', 'true');
    });
  }

  function decorateRule(node) {
    node.setAttribute('role', 'separator');
  }

  function wrapTable(table) {
    var parent = table.parentNode;
    if (parent && parent.classList && parent.classList.contains('table-scroll')) return;
    var wrap = el('div', { className: 'table-scroll', tabIndex: '0', role: 'region' });
    wrap.setAttribute('aria-label', '表格（可横向滚动）');
    parent.replaceChild(wrap, table);
    wrap.appendChild(table);
  }

  function guardInput(node) {
    if ((node.getAttribute('type') || '').toLowerCase() !== 'checkbox') {
      node.remove();
    }
  }

  var LANG_ALIASES = {
    js: 'javascript', jsx: 'javascript', mjs: 'javascript', cjs: 'javascript',
    ts: 'typescript', tsx: 'typescript', py: 'python', rb: 'ruby',
    sh: 'bash', shell: 'bash', zsh: 'bash', console: 'bash',
    yml: 'yaml', md: 'markdown', 'c++': 'cpp', 'c#': 'csharp', cs: 'csharp',
    html: 'xml', vue: 'xml', htm: 'xml', svg: 'xml',
    text: 'plaintext', txt: 'plaintext', plain: 'plaintext',
    ps1: 'powershell', pwsh: 'powershell', dockerfile: 'dockerfile',
    objectivec: 'objectivec', golang: 'go', make: 'makefile'
  };

  function decorateCodeBlock(pre) {
    var code = pre.querySelector('code');
    if (!code) return;
    var cls = code.className || '';
    var match = /(?:language|lang)-([\w+#.-]+)/.exec(cls);
    var declared = match ? match[1].toLowerCase() : '';
    var resolved = LANG_ALIASES[declared] || declared;
    var text = code.textContent;

    if (resolved && typeof hljs !== 'undefined' && hljs.getLanguage(resolved)) {
      try {
        code.innerHTML = hljs.highlight(text, {
          language: resolved,
          ignoreIllegals: true
        }).value;
      } catch (err) {
        // A highlighter failure must degrade to plain code, never break the page.
      }
    }
    code.classList.add('hljs');
    if (declared) pre.setAttribute('data-lang', declared);

    var parent = pre.parentNode;
    var existing = parent && parent.classList && parent.classList.contains('code-block');
    if (!existing) {
      var wrap = el('div', { className: 'code-block' });
      parent.replaceChild(wrap, pre);
      wrap.appendChild(pre);
      parent = wrap;
    }
    if (parent.querySelector(':scope > .code-copy')) return;

    var label = el('span', { text: '复制' });
    var copy = el('button', {
      className: 'code-copy t-interactive',
      type: 'button',
      'aria-label': '复制代码到剪贴板'
    }, [MD.icon('copy', { size: 'sm' }), label]);

    copy.addEventListener('click', function () {
      MD.util.copyText(text).then(function (ok) {
        copy.setAttribute('data-copied', ok ? 'true' : 'false');
        label.textContent = ok ? '已复制' : '复制失败';
        window.setTimeout(function () {
          copy.removeAttribute('data-copied');
          label.textContent = '复制';
        }, 1600);
      });
    });
    parent.appendChild(copy);
  }

  /** `> [!NOTE]` -> a structured callout. Runs after sanitising, on real nodes. */
  function convertCallout(blockquote) {
    if (blockquote.classList.contains('callout')) return;
    var firstP = null;
    for (var child = blockquote.firstElementChild; child; child = child.nextElementSibling) {
      if (child.tagName === 'P') { firstP = child; break; }
      break;
    }
    if (!firstP) return;
    var raw = firstP.textContent.trim();
    var match = /^\[!(\w+)\]/i.exec(raw);
    if (!match) return;
    var kind = CALLOUT_KEYWORDS[match[1].toUpperCase()];
    if (!kind) return;

    var body = el('div', { className: 'callout__body' });

    // Collect every node from the marker paragraph onward BEFORE mutating.
    // A removed node loses its sibling pointers, so reading nextSibling after
    // `firstP.remove()` returns null — the remaining paragraphs would then be
    // stranded outside the body and the title would paint below them.
    var tail = [];
    for (var node = firstP; node; node = node.nextSibling) tail.push(node);

    var rest = raw.slice(match[0].length).replace(/^[\s\u00a0]+/, '');
    if (rest) {
      firstP.textContent = rest;
    } else {
      tail.shift(); // drop the marker-only paragraph
      firstP.remove();
    }
    tail.forEach(function (n) { body.appendChild(n); });

    var title = el('p', { className: 'callout__title' });
    title.textContent = match[1].toUpperCase();
    blockquote.classList.add('callout', 'callout--' + kind);
    blockquote.appendChild(title);
    blockquote.appendChild(body);
  }

  function markTaskLists(root) {
    var boxes = root.querySelectorAll('input[type="checkbox"]');
    Array.prototype.forEach.call(boxes, function (box) {
      var item = box.closest('li');
      if (!item) { box.remove(); return; }
      var isChecked = box.hasAttribute('checked') || box.checked;
      if (item.parentNode) item.parentNode.classList.add('contains-task-list');
      item.classList.add('task-list-item');
      if (isChecked) item.setAttribute('data-checked', 'true');
      // Rebuild as a clean disabled control: the markdown source is the single
      // source of truth, so clicking a box must never desync the document.
      var fresh = el('input', {
        type: 'checkbox',
        disabled: true,
        tabIndex: '-1',
        'aria-hidden': 'true'
      });
      if (isChecked) fresh.setAttribute('checked', 'checked');
      box.parentNode.replaceChild(fresh, box);
    });
  }

  /* ==========================================================================
   * 5. Public API
   * ======================================================================= */

  /**
   * render(source) -> { html, headings, empty }
   * Pure: the same source always yields the same structure, so callers may
   * cache or diff on it freely.
   */
  function render(source) {
    var text = source === null || source === undefined ? '' : String(source);
    var extracted = extractMath(text);
    var parsed = parseMarkdown(extracted.source);
    var clean = sanitize(parsed);

    var host = el('div');
    host.innerHTML = clean;
    var headings = postProcess(host);
    restoreMath(host, extracted.store);

    return {
      html: host.innerHTML,
      headings: headings,
      empty: isEmptyDoc(text)
    };
  }

  /** Headings only. Parses, so the outline can never drift from the preview. */
  function outline(source) {
    return render(source).headings;
  }

  /** True when the source has no visible content (blank, or only whitespace). */
  function isEmptyDoc(source) {
    return !String(source).trim();
  }

  /** One-line plain-text excerpt for library cards. */
  function excerpt(source, max) {
    var text = String(source)
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/~~~[\s\S]*?~~~/g, ' ')
      .replace(/`([^`]*)`/g, '$1')
      .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/^\s{0,3}#{1,6}\s+/gm, '')
      .replace(/^\s{0,3}>\s?/gm, '')
      .replace(/^\s{0,3}([-*+]|\d{1,9}[.)])\s+/gm, '')
      .replace(/^\s{0,3}(?:[-*_]\s*){3,}$/gm, ' ')
      .replace(/[*_~`]{1,3}/g, '')
      .replace(/\$\$?[^$]*\$\$?/g, ' ')
      .replace(/<[^>]*>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    return truncate(text, max || 160);
  }

  MD.md = {
    render: render,
    outline: outline,
    excerpt: excerpt,
    sanitize: sanitize,
    isEmptyDoc: isEmptyDoc,
    langAlias: function (lang) {
      var key = String(lang).toLowerCase();
      return LANG_ALIASES[key] || key;
    }
  };
})(window.MD = window.MD || {});
